INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 10, 'theory', 'Quiz: dictionary techniques');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 10, 0, 'a = {"x": 1, "y": 2}; b = {"y": 20}. What is a | b?', '["{\"x\": 1, \"y\": 2}", "{\"x\": 1, \"y\": 20}", "{\"y\": 20}", "Error: cannot merge"]', 1, 'When a key appears in both, the right dictionary wins; the other pairs are kept.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 10, 1, 'What does dict(zip(["a", "b"], [1, 2])) return?', '["{\"a\": 1, \"b\": 2}", "[(\"a\", 1), (\"b\", 2)]", "{1: \"a\", 2: \"b\"}", "An error"]', 0, 'zip glues the elements into pairs, and dict turns the pairs into a dictionary: the first item is the key, the second is the value.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 10, 2, 'What does groups.setdefault(key, []).append(x) do?', '["Always replaces the list under the key with an empty one", "Appends x to the list under the key, creating an empty list if the key was missing", "Fails with an error if the key is missing", "Removes the key from the dictionary"]', 1, 'setdefault returns the existing value, or stores and returns the fallback, so you can call append right away.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 10, 3, 'sales = {"tea": 5, "coffee": 9}. What does max(sales, key=sales.get) return?', '["\"tea\"", "\"coffee\"", "9", "5"]', 1, 'max iterates over the keys, and key=sales.get compares them by their values: the largest belongs to "coffee". The key is returned.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 10, 4, 'shared = dict.fromkeys(["a", "b"], []); shared["a"].append(1). What is shared["b"]?', '["[]", "[1]", "None", "KeyError"]', 1, 'fromkeys puts the same list under every key. These are references, not copies.');
